              <button onClick={onConfirm} disabled={timer > 0} className={`flex-1 py-3 rounded-xl font-black text-[10px] uppercase tracking-widest transition-all ${timer > 0 ? 'bg-zinc-900 border border-zinc-800 text-zinc-600 cursor-not-allowed' : 'bg-rose-600 hover:bg-rose-500 text-white shadow-rose-900/50'}`}>
                {timer > 0 ? `Wait ${timer}s` : 'Confirm'}
