          grossPnl = positionSize * ((entryPrice - exitPrice) / entryPrice);
      }

      // 4. Net & Payout
      const netPnl = grossPnl - totalFees;
      const totalPayout = collateral + netPnl;
      const roi = (netPnl / collateral) * 100;

      return {
          grossPnl,
          totalFees,
          netPnl,
          totalPayout,
          roi,
          isProjected
      };
  }, [collateral, leverage, entryPrice, side, tpslEnabled, tpPriceInput, tpPriceNum, positionSize]);


