                            <div className={`h-full transition-all duration-150 ${leverage > 100 ? 'bg-gradient-to-r from-emerald-500 via-amber-500 to-rose-500' : 'bg-emerald-500'}`} style={{ width: `${(leverage / maxLeverage) * 100}%` }}></div>
                        </div>
                        <input type="range" min="1" max={maxLeverage} step="1" value={leverage} onChange={(e) => setLeverage(Number(e.target.value))} className="absolute inset-0 w-full h-full opacity-0 cursor-pointer z-10" />
                        <div className="absolute w-4 h-4 bg-white rounded-full shadow-lg border-2 border-zinc-900 pointer-events-none transition-all duration-150" style={{ left: `calc(${(leverage / maxLeverage) * 100}% - 8px)` }}></div>
                    </div>
                    <div className="flex justify-between text-[9px] font-bold text-zinc-600 font-mono items-center">
                        <span>1x</span>
                        <span>{isDegenMode ? '500x' : '50x'}</span>
                        <span className={isDegenMode ? 'text-rose-500' : ''}>{maxLeverage}x</span>
                        <button onClick={toggleLock} className="ml-2 hover:text-white transition-colors" title={isDegenMode ? "Lock Leverage" : "Unlock High Leverage"}>
                            {isDegenMode ? <Unlock size={10} className="text-rose-500"/> : <Lock size={10}/>}
                        </button>
                    </div>
                </div>

                {/* TP / SL */}
                <div className="space-y-3">
                    <div className="flex items-center gap-2 cursor-pointer group" onClick={() => setTpslEnabled(!tpslEnabled)}>
                        <div className={`w-4 h-4 rounded border flex items-center justify-center transition-all ${tpslEnabled ? 'bg-emerald-500 border-emerald-500' : 'bg-transparent border-zinc-700 group-hover:border-zinc-500'}`}>
                            {tpslEnabled && <Check size={10} className="text-black stroke-[4px]" />}
                        </div>
                        <label className="text-[10px] font-bold text-zinc-300 uppercase cursor-pointer group-hover:text-white">Take Profit / Stop Loss</label>
                    </div>

                    {tpslEnabled && (
                        <div className="space-y-3 animate-in fade-in slide-in-from-top-1 duration-200">
                            {/* TP Row */}
                            <div className="grid grid-cols-2 gap-2">
                                <div className="bg-[#18181b] border border-white/5 rounded-lg p-2 focus-within:border-emerald-500/50 transition-colors">
                                    <label className="text-[8px] font-bold text-zinc-500 uppercase block mb-1">TP Price</label>
                                    <input type="text" value={tpPriceInput} onChange={(e) => handleTpPriceChange(e.target.value)} className="bg-transparent text-xs font-mono font-bold text-white w-full outline-none" />
                                </div>
                                <div className="bg-[#18181b] border border-white/5 rounded-lg p-2 focus-within:border-emerald-500/50 transition-colors">
                                    <label className="text-[8px] font-bold text-zinc-500 uppercase block mb-1">Gain %</label>
                                    <input type="text" value={tpPercentInput} onChange={(e) => handleTpPercentChange(e.target.value)} className="bg-transparent text-xs font-mono font-bold text-emerald-500 w-full outline-none" />
                                </div>
                            </div>
                            {/* SL Row */}
                            <div className="grid grid-cols-2 gap-2">
                                <div className="bg-[#18181b] border border-white/5 rounded-lg p-2 focus-within:border-rose-500/50 transition-colors">
                                    <label className="text-[8px] font-bold text-zinc-500 uppercase block mb-1">SL Price</label>
                                    <input type="text" value={slPriceInput} onChange={(e) => handleSlPriceChange(e.target.value)} className="bg-transparent text-xs font-mono font-bold text-white w-full outline-none" />
                                </div>
                                <div className="bg-[#18181b] border border-white/5 rounded-lg p-2 focus-within:border-rose-500/50 transition-colors">
                                    <label className="text-[8px] font-bold text-zinc-500 uppercase block mb-1">Loss %</label>
                                    <input type="text" value={slPercentInput} onChange={(e) => handleSlPercentChange(e.target.value)} className="bg-transparent text-xs font-mono font-bold text-rose-500 w-full outline-none" />
                                </div>
                            </div>
                        </div>
                    )}
                </div>

                {/* Footer Area (Fixed at bottom or scrolling with content? previously scrolling) */}
                <div className="mt-auto pt-4 space-y-3">
                   {/* 1. Primary Outcome Card (Always Visible) */}
                   {outcomeSimulation && (
                       <div className={`p-4 rounded-xl border transition-colors ${outcomeSimulation.netPnl > 0 ? 'bg-emerald-500/5 border-emerald-500/20' : 'bg-zinc-900/50 border-white/10'}`}>
                            {/* Header: ROI & PnL */}
                            <div className="flex justify-between items-end mb-2">
                                <div className="flex flex-col">
                                    <span className="text-[9px] font-black text-zinc-500 uppercase tracking-widest mb-0.5">Est. ROI</span>
                                    <span className={`text-xl font-mono font-black leading-none ${outcomeSimulation.roi >= 0 ? 'text-emerald-400' : 'text-rose-400'}`}>
