                                    </span>
                                </div>
                                <div className="flex flex-col items-end">
                                    <span className="text-[9px] font-black text-zinc-500 uppercase tracking-widest mb-0.5">Net Profit</span>
                                    <span className={`text-sm font-mono font-bold ${outcomeSimulation.netPnl >= 0 ? 'text-emerald-500' : 'text-rose-500'}`}>
                                        {outcomeSimulation.netPnl >= 0 ? '+' : ''}{outcomeSimulation.netPnl.toLocaleString('en-US', {style: 'currency', currency: 'USD'})}
                                    </span>
                                </div>
                            </div>

                            {/* Footer: Payout */}
                            <div className="pt-2 border-t border-white/5 flex justify-between items-center">
                                <span className="text-[10px] font-bold text-zinc-400">Total Payout</span>
                                <span className="text-xs font-mono font-bold text-white">
                                    ${outcomeSimulation.totalPayout.toLocaleString('en-US', {maximumFractionDigits: 2})}
                                </span>
                            </div>
                       </div>
                   )}

                   {/* 2. Collapsible Details (Progressive Disclosure) */}
                   <div className="border border-white/5 rounded-xl overflow-hidden bg-[#0a0a0a]">
                        <button 
                            onClick={() => setShowOrderDetails(!showOrderDetails)}
                            className="w-full flex items-center justify-between p-3 bg-zinc-900/30 hover:bg-zinc-900/50 transition-colors group"
                        >
                            <div className="flex items-center gap-2">
                                <Info size={12} className="text-zinc-500 group-hover:text-zinc-300"/>
                                <span className="text-[10px] font-bold text-zinc-500 group-hover:text-zinc-300 uppercase tracking-widest">Fees & Rates</span>
                            </div>
                            <ChevronDown size={12} className={`text-zinc-600 transition-transform duration-300 ${showOrderDetails ? 'rotate-180' : ''}`}/>
                        </button>

                        {showOrderDetails && (
                            <div className="px-3 pb-3 space-y-2 animate-in slide-in-from-top-2 fade-in duration-200">
                                <div className="h-px bg-white/5 mb-2"></div>
                                <div className="flex justify-between text-[10px]">
                                    <span className="text-zinc-500">Entry (Incl. Spread)</span>
                                    <span className="font-mono text-zinc-300">${executionPrice.toLocaleString('en-US', {minimumFractionDigits: 2})}</span>
                                </div>
                                <div className="flex justify-between text-[10px]">
                                    <span className="text-zinc-500">Funding / 1h</span>
                                    <span className={`font-mono ${isHighFunding ? 'text-amber-500' : 'text-zinc-400'}`}>-${hourlyFundingCost.toFixed(2)}</span>
                                </div>
                                <div className="flex justify-between text-[10px]">
                                    <span className="text-zinc-500">Network Gas</span>
