                                    <span className="font-mono text-rose-500">1.00%</span>
                                </div>
                            </div>
                        )}
                   </div>

                   {/* 3. Action Button */}
                   <button onClick={handleExecute} className={`w-full py-4 rounded-xl font-black text-xs uppercase tracking-widest shadow-lg transition-all active:scale-[0.98] ${themeBg} text-black hover:opacity-90`}>
                        {side === 'long' ? 'Open Long' : 'Open Short'}
                   </button>
                </div>

            </div>
        </aside>

        {/* Token Selector Modal (Reusable Logic) */}
        {isTokenSelectorOpen && (
            <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/50 backdrop-blur-sm" onClick={() => setIsTokenSelectorOpen(false)}>
