                                        <span className="text-sm font-bold text-white block">{sym}</span>
                                    </div>
                                </div>
                                {pinnedTickers.includes(sym) && <Check size={14} className="text-emerald-500" />}
                            </button>
                        ))}
                    </div>
                </div>
            </div>
        )}

      </div>
    </div>
  );
};

