import React, { useState, useMemo, useEffect, useCallback } from 'react';
import { 
  ChevronDown, 
  Maximize2, 
  Settings2, 
  Lock, 
  Unlock, 
  Crosshair, 
  PenTool, 
  Hash, 
  Globe, 
  Skull, 
  Minus, 
  Plus, 
  Wallet,
  TrendingUp,
  AlertTriangle,
  RefreshCw,
  Check,
  Percent,
  DollarSign,
  ShieldCheck,
  Info,
  Flame,
  Clock,
  Zap,
  Coins,
  Calculator,
  ArrowRight,
  Flag,
  X
} from 'lucide-react';
import { createPortal } from 'react-dom';

// --- TYPES ---
interface Candle {
  time: number;
  open: number;
  high: number;
  low: number;
  close: number;
}

// --- SYNTHETIC CHART GENERATOR (BTC Logic) ---
const generateSyntheticCandles = (count: number, startPrice: number): Candle[] => {
  const candles: Candle[] = [];
  let currentPrice = startPrice;
  const now = Date.now();
  const timeStep = 15 * 60 * 1000; // 15 min

  for (let i = count; i > 0; i--) {
    const volatility = currentPrice * 0.002; // 0.2% volatility per candle
    const trend = (Math.random() - 0.5) * volatility * 0.5; // Slight drift

    const open = currentPrice;
    const close = open + ((Math.random() - 0.5) * volatility) + trend;

    // Wicks
    const high = Math.max(open, close) + (Math.random() * volatility * 0.8);
    const low = Math.min(open, close) - (Math.random() * volatility * 0.8);

    candles.push({
      time: now - (i * timeStep),
      open,
      high,
      low,
      close
    });

    currentPrice = close;
  }
  return candles;
};

// --- SANITY CHECK MODAL ---
interface SanityCheckProps {
  isOpen: boolean;
  onClose: () => void;
  onConfirm: () => void;
  leverage: number;
  side: 'long' | 'short';
  liqPrice: number;
  distance: string;
}

const SanityCheckModal: React.FC<SanityCheckProps> = ({ isOpen, onClose, onConfirm, leverage, side, liqPrice, distance }) => {
  const [timer, setTimer] = useState(3);

  useEffect(() => {
    let interval: ReturnType<typeof setInterval>;
    if (isOpen) {
      setTimer(3);
      interval = setInterval(() => {
        setTimer((prev) => (prev > 0 ? prev - 1 : 0));
      }, 1000);
    }
    return () => clearInterval(interval);
  }, [isOpen]);

  if (!isOpen) return null;

  return createPortal(
    <div className="fixed inset-0 z-[9999] flex items-center justify-center bg-black/80 backdrop-blur-md animate-in fade-in duration-200">
